import{_ as t,o as a,c as o,a4 as r}from"./chunks/framework.CQGI5ZO3.js";const h=JSON.parse('{"title":"xs-compat(7)","description":"Know the native path, delegation behavior, and platform boundaries.","frontmatter":{"title":"xs-compat(7)","description":"Know the native path, delegation behavior, and platform boundaries.","manual":"xs-compat(7)","manualName":"Compatibility","sectionNumber":"7"},"headers":[],"relativePath":"compatibility.md","filePath":"compatibility.md"}'),s={name:"compatibility.md"};function d(n,e,c,i,l,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="xs-compat-7" tabindex="-1">xs-compat(7) <a class="header-anchor" href="#xs-compat-7" aria-label="Permalink to &quot;xs-compat(7)&quot;">​</a></h1><div class="manual-deck"><strong>Compatibility</strong><p>Know the native path, delegation behavior, and platform boundaries.</p></div><h2 id="protocol" tabindex="-1">NATIVE PROTOCOL <a class="header-anchor" href="#protocol" aria-label="Permalink to &quot;NATIVE PROTOCOL {#protocol}&quot;">​</a></h2><p>xsync is a rsync work-alike, not a wire-compatible rsync implementation. Current protocol 4 interoperates with protocols 4 and 3. Capabilities are intersected during negotiation; missing requested semantics fail or delegate before destination writes.</p><h2 id="fallback" tabindex="-1">FALLBACK <a class="header-anchor" href="#fallback" aria-label="Permalink to &quot;FALLBACK {#fallback}&quot;">​</a></h2><div class="example-caption">Require native xsync</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">--no-fallback</span><span style="color:#DEDEDE;"> -azP</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> user@host:/backup/</span></span></code></pre></div><p>By default, unsupported flags, missing remote helpers, unsupported protocol versions, and daemon URLs can re-execute a real rsync from PATH. One stderr notice explains the delegation. Original arguments are retained after xs-only worker/clone/atomic extensions are removed.</p><p>Malformed protocol data and failures during a transfer do not trigger fallback. An explicit <code>--rsync-path</code> is retained, so it must also be an appropriate rsync command if delegation is needed.</p><h2 id="delegated" tabindex="-1">DELEGATED OPTIONS <a class="header-anchor" href="#delegated" aria-label="Permalink to &quot;DELEGATED OPTIONS {#delegated}&quot;">​</a></h2><div class="manual-table-wrap"><table><thead><tr><th scope="col">Request</th><th scope="col">Behavior</th></tr></thead><tbody><tr><td><code>-b / --backup</code></td><td>Delegate to rsync</td></tr><tr><td><code>--compare-dest / --copy-dest</code></td><td>Delegate to rsync</td></tr><tr><td><code>--append / --partial-dir</code></td><td>Delegate to rsync</td></tr><tr><td><code>--remove-source-files</code></td><td>Delegate to rsync</td></tr><tr><td><code>host::module / rsync://</code></td><td>Delegate daemon transport to rsync</td></tr><tr><td><code>--fsync / --preallocate / --contimeout</code></td><td>Unsupported natively; delegate or fail in strict mode</td></tr></tbody></table></div><p>Options such as <code>--skip-compress</code>, <code>--block-size</code>, <code>--checksum-choice</code>, <code>--log-file-format</code>, and <code>--debug</code> also delegate. Native <code>--compress-choice</code> accepts zstd or none.</p><h2 id="differences" tabindex="-1">BEHAVIORAL DIFFERENCES <a class="header-anchor" href="#differences" aria-label="Permalink to &quot;BEHAVIORAL DIFFERENCES {#differences}&quot;">​</a></h2><div class="manual-table-wrap"><table><thead><tr><th scope="col">Area</th><th scope="col">xsync behavior</th></tr></thead><tbody><tr><td>New byte-copied files</td><td>Atomic temporary file + rename by default</td></tr><tr><td>Local compression</td><td>-z has no compression effect locally</td></tr><tr><td>APFS clones</td><td>Can preserve more metadata than -a requests</td></tr><tr><td>Output ordering</td><td>Non-terminal file output is sorted at end of run</td></tr><tr><td>%b</td><td>File-content bytes before compression; not rsync wire bytes</td></tr><tr><td>JSON progress</td><td>Requires native structured events; never supplied by fallback</td></tr></tbody></table></div><h2 id="platforms" tabindex="-1">PLATFORM BOUNDARIES <a class="header-anchor" href="#platforms" aria-label="Permalink to &quot;PLATFORM BOUNDARIES {#platforms}&quot;">​</a></h2><p>macOS and Linux are current targets. Creation times and BSD flags are macOS features; native remote ACLs need matching styles. Unsupported macOS socket metadata requests can return exit 23. Deep source paths beyond PATH_MAX report path-length errors.</p><p>Native Windows support, additional protocols, and remote-to-remote copies are proposed follow-on work in the GUI backlog. They are not current CLI capabilities.</p><h2 id="noops" tabindex="-1">DOCUMENTED NO-OPS <a class="header-anchor" href="#noops" aria-label="Permalink to &quot;DOCUMENTED NO-OPS {#noops}&quot;">​</a></h2><p><code>-s</code>/<code>--protect-args</code>/<code>--secluded-args</code> need no extra action because native paths travel as protocol data. Blocking-I/O switches cannot alter the internally polled pipe transport. <code>--no-motd</code> has no native daemon greeting to suppress.</p>',19)])])}const u=t(s,[["render",d]]);export{h as __pageData,u as default};
